<script lang="ts">
 import {onMount} from 'svelte';
 type Photo={key:string;url:string;name?:string;width?:number;height?:number};
 type Album={id:string;name:string;description?:string;date?:string;location?:string;tags?:string[];encrypted?:boolean;password?:string;private?:boolean;cover?:string;coverUrl?:string;photos?:Photo[];photoOrder?:string[];photoCount?:number};
 let {albumId=''}:{albumId?:string}=$props();
 let albums:Album[]=$state([]);let loading=$state(true);let problem=$state('');let route=$state<'smart'|'cache'|'direct'>('smart');let query=$state('');let tag=$state('');let active:Photo|null=$state(null);let activeIndex=$state(0);
 const origin='/file/';
 function imageUrl(key:string){return origin+key.split('/').map(encodeURIComponent).join('/')}
 function sourcePhoto(p:Photo){if(!p?.key)return '';if(route==='direct')return p.url||imageUrl(p.key);return `/api/gallery-image?key=${encodeURIComponent(p.key)}`}
 function normalize(raw:any):Album|null {if(!raw||!raw.id||!raw.name)return null;const protectedAlbum=Boolean(raw.encrypted||raw.private||raw.protected||raw.password||raw.passwordHash);const keys=Array.isArray(raw.photoOrder)?raw.photoOrder.filter((x:any)=>typeof x==='string'):[];const photos:Photo[]=protectedAlbum?[]:Array.isArray(raw.photos)?raw.photos.filter((x:any)=>typeof x?.key==='string').map((x:any)=>({key:x.key,url:x.url||imageUrl(x.key),name:x.name,width:x.width,height:x.height})):keys.map((key:string)=>({key,url:imageUrl(key)}));return {id:String(raw.id),name:String(raw.name),description:String(raw.description||''),date:String(raw.date||''),location:String(raw.location||''),tags:Array.isArray(raw.tags)?raw.tags:[],encrypted:protectedAlbum,cover:raw.cover,coverUrl:raw.coverUrl||(!protectedAlbum&&raw.cover?imageUrl(raw.cover):''),photos,photoCount:Number(raw.photoCount||photos.length)}}
 async function load(){loading=true;problem='';try{const r=await fetch('/api/gallery-public',{cache:'no-store'});if(!r.ok)throw Error('Cloudflare 相册接口 '+r.status);const d=await r.json();if(!Array.isArray(d.albums))throw Error('相册响应无效');albums=d.albums.map(normalize).filter(Boolean) as Album[];if(albums.length===0)throw Error('目前没有公开相册')}
 catch(e){try{const r=await fetch('/assets/gallery-historical-snapshot.json');if(!r.ok)throw Error();const d=await r.json();albums=(d.albums||[]).map(normalize).filter(Boolean) as Album[];problem='云端暂时不可用，当前显示最近一次公开快照';}catch{problem='暂时无法读取相册；请检查图床服务';albums=[]}}finally{loading=false}}
 onMount(()=>{try{const saved=localStorage.getItem('firefly-gallery-route');if(saved==='cache'||saved==='smart'||saved==='direct')route=saved;}catch{}load();const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')active=null;if(!active)return;if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)});
 function setRoute(v:'smart'|'cache'|'direct'){route=v;try{localStorage.setItem('firefly-gallery-route',v)}catch{}}
 let selected=$derived(albumId?albums.find(a=>a.id===albumId):null);
 let filtered=$derived(albums.filter(a=>!albumId&&(!query||`${a.name} ${a.description||''} ${(a.tags||[]).join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&(!tag||(a.tags||[]).includes(tag))));
 let tags=$derived([...new Set(albums.flatMap(a=>a.tags||[]))]);
 function show(p:Photo,i:number){active=p;activeIndex=i}
 function step(delta:number){if(!selected||!active)return;const ps=selected.photos||[];if(!ps.length)return;activeIndex=(activeIndex+ps.length+delta)%ps.length;active=ps[activeIndex]}
</script>
<div class="gallery-recovery">
 <section class="card-base gallery-route" aria-label="图片加载线路">
  <div class="route-head"><small>PHOTO DELIVERY</small><h2>图片加载线路 ✧</h2><p>选择更适合你的加载方式，照片品质始终如一。</p></div>
  <div class="route-choices" role="group" aria-label="图片加载线路选择">
   <button class:active={route==='smart'} aria-pressed={route==='smart'} onclick={()=>setRoute('smart')}>✦ <b>智能加速</b><small>优先使用 EdgeOne 缓存</small></button>
   <button class:active={route==='cache'} aria-pressed={route==='cache'} onclick={()=>setRoute('cache')}>☁ <b>缓存线路</b><small>EdgeOne 图片缓存</small></button>
   <button class:active={route==='direct'} aria-pressed={route==='direct'} onclick={()=>setRoute('direct')}>↗ <b>直连原图</b><small>直接从图床加载</small></button>
  </div><p class="route-tip">ⓘ 线路选择自动保存；点击图片查看原始分辨率。</p>
 </section>
 {#if problem}<p class="gallery-status" role="status">{problem}</p>{/if}
 {#if loading}<div class="card-base gallery-status">正在加载相册…</div>{:else if albumId}
  {#if selected}
   <div class="card-base gallery-heading"><a href="/gallery/">← 所有相册</a><h2>{selected.name}</h2><p>{selected.description}</p><small>{selected.date} · {selected.location}</small></div>
   {#if selected.encrypted}<div class="card-base gallery-status">此相册受保护，不会公开其图片。请在原相册授权访问。</div>
   {:else}<div class="gallery-photos">{#each selected.photos||[] as p,i (p.key)}<button title={p.name||p.key} onclick={()=>show(p,i)}><img src={sourcePhoto(p)} alt={p.name||selected.name} loading={i<3?'eager':'lazy'} decoding="async" onerror={e=>{if(route!=='direct'){(e.currentTarget as HTMLImageElement).src=p.url||imageUrl(p.key)}}}/></button>{/each}</div>{/if}
  {:else}<div class="card-base gallery-status">没有找到相册。<a href="/gallery/">返回相册</a></div>{/if}
 {:else}
  <div class="card-base gallery-filters"><label>搜索相册 <input type="search" placeholder="相册名称、描述或标签" bind:value={query}/></label><div class="tag-row"><button class:active={!tag} onclick={()=>tag=''}>全部</button>{#each tags as t}<button class:active={tag===t} onclick={()=>tag=t}>{t}</button>{/each}</div></div>
  <div class="gallery-albums">{#each filtered as a (a.id)}<a class="card-base album-tile" href={`/gallery/${encodeURIComponent(a.id)}/`}><div class="album-cover">{#if a.coverUrl&&!a.encrypted}<img src={route==='direct'?a.coverUrl:sourcePhoto({key:a.cover||a.photos?.[0]?.key||'',url:a.coverUrl})} alt={a.name} loading="lazy"/>{:else}<span>{a.encrypted?'🔒':'相册'}</span>{/if}</div><div class="album-info"><h3>{a.name}</h3><p>{a.description}</p><small>{a.date} · {a.photoCount||a.photos?.length||0} 张</small></div></a>{:else}<div class="card-base gallery-status">没有匹配的相册</div>{/each}</div>
 {/if}
 {#if active}<div class="gallery-lightbox" role="presentation" onclick={e=>{if(e.target===e.currentTarget)active=null}}><button class="lightbox-close" onclick={()=>active=null} aria-label="关闭大图">✕</button><button onclick={()=>step(-1)} aria-label="上一张">‹</button><img src={active.url||imageUrl(active.key)} alt={active.name||''}/><button onclick={()=>step(1)} aria-label="下一张">›</button></div>{/if}
</div>
<style>
 .gallery-recovery{display:grid;gap:1rem}.gallery-route,.gallery-filters,.gallery-heading{padding:1.25rem 1.5rem}.route-head small{letter-spacing:.16em;font-size:.68rem;opacity:.65}.route-head h2,.gallery-heading h2{font-size:1.4rem;font-weight:750}.route-head p,.route-tip,.gallery-heading p,.album-info p{opacity:.7;font-size:.91rem}.route-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.6rem;margin:.85rem 0}.route-choices button{display:grid;text-align:left;gap:.25rem;border:1px solid var(--line-divider);padding:.8rem;border-radius:.8rem;background:var(--card-bg)}.route-choices button.active,.tag-row button.active{border-color:var(--primary);box-shadow:0 0 0 1px var(--primary)}.route-choices small{font-size:.74rem;opacity:.65}.gallery-filters input{background:transparent;border:1px solid var(--line-divider);border-radius:.5rem;padding:.45rem .7rem;width:min(100%,380px);display:block;margin-top:.45rem}.tag-row{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.8rem}.tag-row button{border:1px solid var(--line-divider);border-radius:1rem;padding:.3rem .7rem}.gallery-albums{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:1rem}.album-tile{overflow:hidden;transition:transform .2s}.album-tile:hover{transform:translateY(-3px)}.album-cover{height:180px;background:color-mix(in srgb,var(--primary) 12%,transparent);display:flex;align-items:center;justify-content:center}.album-cover img{width:100%;height:100%;object-fit:cover}.album-info{padding:1rem}.album-info h3{font-weight:750;font-size:1.1rem}.album-info small,.gallery-heading small{opacity:.55}.gallery-status{text-align:center;padding:2rem}.gallery-photos{columns:3 200px;column-gap:.65rem}.gallery-photos button{display:block;width:100%;break-inside:avoid;margin-bottom:.65rem;border-radius:.6rem;overflow:hidden}.gallery-photos img{display:block;width:100%;height:auto;transition:transform .2s}.gallery-photos button:hover img{transform:scale(1.025)}.gallery-lightbox{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.93);display:flex;align-items:center;justify-content:space-around;gap:.35rem;padding:1rem}.gallery-lightbox img{object-fit:contain;max-width:82vw;max-height:92vh}.gallery-lightbox button{color:white;font-size:2.3rem;padding:.65rem}.lightbox-close{position:absolute;right:1rem;top:.35rem;font-size:1.3rem!important}@media(max-width:640px){.route-choices{grid-template-columns:1fr}.gallery-lightbox img{max-width:78vw}}
</style>
